def luminance(c):
    v=[int(c[i:i+2],16)/255 for i in (1,3,5)]
    v=[x/12.92 if x<=.04045 else ((x+.055)/1.055)**2.4 for x in v]
    return .2126*v[0]+.7152*v[1]+.0722*v[2]
def contrast(a,b):
    x,y=sorted([luminance(a),luminance(b)])
    return (y+.05)/(x+.05)
PAIRS=[]
for theme, t in TOKENS['themes'].items():
    for fg,bg in [('text','background'),('text','surface'),('text','surfaceSubtle'),('muted','background'),('muted','surface'),('muted','surfaceSubtle'),('accent','background'),('accent','surface'),('onAccent','accent'),('success','successSurface'),('warning','warningSurface'),('danger','dangerSurface'),('danger','surface'),('focus','surface'),('controlBorder','surface'),('disabledText','disabled')]:
        ratio=contrast(t[fg],t[bg]); threshold=3 if fg in ('focus','controlBorder') else 4.5
        PAIRS.append({'theme':theme,'foreground':fg,'background':bg,'ratio':round(ratio,2),'minimum':threshold,'pass':ratio>=threshold})
assert all(p['pass'] for p in PAIRS), [p for p in PAIRS if not p['pass']]
(ROOT/'design-tokens.json').write_text(json.dumps(TOKENS,ensure_ascii=False,indent=2))
(ROOT/'qa/contrast-report.json').write_text(json.dumps(PAIRS,ensure_ascii=False,indent=2))

