def ic(name, cls=''):
    return f'<svg class="icon {cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">{ICONS.get(name,ICONS["info"])}</svg>'

def button(text,go=None,kind='primary',icon=None,attrs='',disabled=False):
    goattr=f' data-go="{go}"' if go else ''
    return f'<button type="button" class="button {kind}"{goattr} {attrs} {"disabled" if disabled else ""}>{ic(icon) if icon else ""}<span>{text}</span></button>'

def status(text,tone='neutral',icon='clock'):
    return f'<span class="status {tone}">{ic(icon)}<span>{text}</span></span>'

def textlink(text,go,icon='chevron'):
    return f'<button class="text-link" type="button" data-go="{go}"><span>{text}</span>{ic(icon)}</button>'

def field(label,value='',hint='',error='',area=False,placeholder='',name='',attrs=''):
    name=name or re.sub(r'[^a-z0-9]','',label.lower()) or 'field'
    klass='field has-error' if error else 'field'
    val=H(value)
    input_=(f'<textarea rows="4" name="{name}" data-persist="{name}" placeholder="{H(placeholder)}" {attrs}>{val}</textarea>' if area else f'<input name="{name}" data-persist="{name}" value="{val}" placeholder="{H(placeholder)}" {attrs}>')
    return f'<label class="{klass}"><span class="field-label">{label}</span>{input_}{f"<span class=field-help>{hint}</span>" if hint else ""}{f"<span class=field-error>{ic(chr(97)+chr(108)+chr(101)+chr(114)+chr(116))}{error}</span>" if error else ""}</label>'

def notice(title,body='',tone='neutral',icon='info',action=''):
    return f'<div class="notice {tone}">{ic(icon)}<div><strong>{title}</strong>{f"<p>{body}</p>" if body else ""}{action}</div></div>'

def choice(label,desc='',checked=False,kind='radio',name='choice',value='',extra='',attrs=''):
    return f'<label class="choice-row {"chosen" if checked else ""}"><input type="{kind}" name="{name}" value="{value or H(label)}" {"checked" if checked else ""} {attrs}><span class="choice-mark"></span><span class="choice-copy"><strong>{label}</strong>{f"<span>{desc}</span>" if desc else ""}{extra}</span></label>'

def context(dispatch=False):
    return f'<div class="context-line">{ic("home")}<span>ул. Садовая, 12<span class="context-meta">Учебный дом{ " · Диспетчер" if dispatch else ""}</span></span></div>'

def heading(title,subtitle='',eyebrow=''):
    return f'<div class="heading">{f"<p class=eyebrow>{eyebrow}</p>" if eyebrow else ""}<h1>{title}</h1>{f"<p class=subtitle>{subtitle}</p>" if subtitle else ""}</div>'

def section(title,body,subtitle='',cls=''):
    return f'<section class="section {cls}"><div class="section-heading"><h2>{title}</h2>{f"<p>{subtitle}</p>" if subtitle else ""}</div>{body}</section>'

def report(text='Лампу заменили. Освещение работает',linked=False):
    return f'<div class="report"><div class="source-label">{ic("person")}<span>Сотрудник сообщил о работе</span></div><blockquote>«{text}»</blockquote><p class="meta">Марина, диспетчер<br>24 сентября, 11:40</p>{f"<div class=report-link>{ic('link')}Связано только со светом · 11:41</div>" if linked else ""}</div>'

def plan(compact=False,door=True):
    return f'<div class="plan"><p class="label">Следующий шаг</p><strong>{"Проверим доводчик" if door else "Проверим освещение"}</strong><div class="meta-row">{ic("person")}<span>Марина, диспетчер</span></div><div class="meta-row">{ic("clock")}<span>Обновление:<br><strong>25 сентября, до 16:00</strong></span></div></div>'

def problem(title='Не горит свет',place='2-й этаж, у лестницы',tone='neutral',state='',body='',actions='',number=1):
    icon='bulb' if number==1 else 'door'
    return f'<article class="problem {tone}"><div class="problem-top"><span class="problem-symbol">{ic(icon)}</span><div><h3>{title}</h3><p class="meta">{place}</p></div><span class="item-number">{number}</span></div>{f"<div class=problem-state>{status(state,tone,'circle-check' if tone=='success' else 'archive' if tone=='withdrawn' else 'clock')}</div>" if state else ""}{body}{actions}</article>'

def light(state='Ожидаем работы',tone='neutral',body='',actions=''):
    return problem(tone=tone,state=state,body=body,actions=actions)

def door(state='Следующий шаг назначен',tone='neutral',body='',actions=''):
    return problem('Не закрывается дверь','Входная дверь подъезда',tone,state,body,actions,2)

def receipt(kind='saved',detail=''):
    saved=kind=='saved'
    return f'<div class="receipt">{ic("file" if saved else "circle-check")}<div><strong>{"Обращение сохранено" if saved else "Принято диспетчером"}</strong><span>{detail or ("24 сентября, 09:10 · система" if saved else "24 сентября, 09:20 · Марина")}</span></div></div>'

def progress(withdrawn=False):
    return f'<div class="progress-summary"><div><p class="label">Проверка результата</p><strong>{"1 в порядке, 1 отозван" if withdrawn else "1 из 2 в порядке"}</strong><p class="meta">По вашему наблюдению</p></div><div class="progress-rail" aria-hidden="true"><i></i><i class="{ "withdrawn" if withdrawn else "pending"}"></i></div></div>'

def timeline(events):
    return '<ol class="timeline">'+''.join(f'<li class="{tone}"><span class="timeline-dot"></span><div><p class="meta">{time}</p><strong>{title}</strong><p>{desc}</p></div></li>' for time,title,desc,tone in events)+'</ol>'

