def invite_error(which):
    messages={'expired':('Срок приглашения истёк','Попросите у обслуживающей организации новое приглашение.'),'used':('Приглашение уже использовано','Оно действует один раз. Обратитесь в организацию за новым доступом.'),'invalid':('Не удалось распознать код','Проверьте код в сообщении организации или запросите новое приглашение.')}
    title,body=messages[which]
    return heading('Приглашение','Доступ выдаёт обслуживающая организация.')+field('Код приглашения','ПРИМЕР',error=title,name='invite-'+which,attrs='aria-invalid="true"')+'<p>'+body+'</p><p class="meta">На экране вымышленное значение, не действующий код доступа.</p>'+textlink('Где получить приглашение','M06')
