def bubble(text,who='bot',buttons=None,time=''):
    return f'<div class="bubble {who}"><div class="bubble-text">{text}</div>{f"<div class=bot-actions>{''.join(button(b[0],b[1] if len(b)>1 else None,'secondary') for b in buttons)}</div>" if buttons else ""}{f"<span class=bubble-time>{time}</span>" if time else ""}</div>'
def botframe(title,messages):
    return {'title':title,'messages':''.join(messages)}
