# Сравнимые компонентные листы.
def comp_section(title,content):
    return f'<section class="component-section"><h2>{title}</h2>{content}</section>'
def sample(label,content):
    return f'<div class="sample"><p class="sample-label">{label}</p>{content}</div>'

def component_foundations(theme):
    t=TOKENS['themes'][theme]
    colorrows=''.join(f'<div class="token-row"><i style="background:{value}"></i><span>{name}</span><code>{value}</code></div>' for name,value in t.items() if name in ['background','surface','surfaceSubtle','text','muted','accent','border','success','warning','danger','focus'])
    pairs=[p for p in PAIRS if p['theme']==theme and p['foreground'] in ['text','muted','onAccent','success','warning','danger'] and p['background'] in ['surface','accent','successSurface','warningSurface','dangerSurface']]
    checks=''.join(f'<div class="contrast-row"><span>{p["foreground"]} / {p["background"]}</span><strong>{p["ratio"]:.2f}:1</strong></div>' for p in pairs)
    return comp_section('Цветовые роли',colorrows)+comp_section('Измеренный контраст',checks+'<p class="meta">Расчёт по значениям sRGB в токенах; не аудит работающего приложения.</p>')+comp_section('Типографика','<div class="type-sample"><h1>Осталась дверь</h1><p class="meta">Заголовок · 27 / 32 px · 650</p><p>Проверим доводчик</p><p class="meta">Основной · 18 / 27 px · 400</p><p class="meta">Обновление: 25 сентября, до 16:00</p><p class="meta">Вторичный · 15 / 22 px · 400</p><div class="large-type"><strong>Крупный текст</strong><p>Высота строки и элементов растёт.</p></div><p class="meta">Режим «Крупный» ×1,25. Отдельно проверяется увеличение до 200%.</p></div>')+comp_section('Геометрия и интервалы','<div class="spacing-ruler">'+''.join(f'<div><i style="width:{n}px;height:{n}px"></i><span>{n}</span></div>' for n in [4,8,12,16,24,32,48])+'</div><p>Карточки 16 px · поля и кнопки 12 px · граница 1 px.</p><p class="meta">Кнопка от 52 px. Цель касания от 44 × 44 px. Контент по сетке 4/8 px.</p>')+comp_section('Один набор иконок','<div class="icon-grid">'+''.join('<span>'+ic(k)+'</span>' for k in ['home','bulb','door','person','file','clock','history','archive','check','edit','filter','settings'])+'</div><p class="meta">Линия 1,7 px / квадрат 24 px. Значимый статус всегда подписан.</p>')

def component_actions(theme):
    button_grid=''
    for label,kind in [('Основная','primary'),('Вторичная','secondary'),('Тихая','quiet'),('Опасная','destructive')]:
        button_grid+=sample(label,'<div class="button-samples">'+button('Продолжить',kind=kind)+button('Нажато',kind=kind,attrs='data-visual-state="pressed"')+button('В фокусе',kind=kind,attrs='data-visual-state="focus"')+button('Недоступно',kind=kind,disabled=True)+button('Сохраняем…',kind=kind,disabled=True,attrs='aria-busy="true"')+'</div>')
    return comp_section('Действия и состояния',button_grid+'<p class="meta">Недоступное действие: рядом объясняем, каких данных не хватает. При отправке повторный запрос не создаётся.</p>')+comp_section('Подписанный ввод',field('Что случилось?','Не горит свет','Укажите место и симптом.',area=True,name='c-text')+field('Где именно?','2-й этаж, у лестницы',name='c-place',attrs='data-visual-state="focus"')+field('Причина отзыва','',error='Укажите причину, чтобы отозвать пункт.',name='c-reason',attrs='aria-invalid="true"')+field('Следующее обновление','25 сентября, до 16:00','Время новой информации, не обещание ремонта.',name='c-date'))+comp_section('Выбор и подтверждение',choice('Не горит свет','Связь выбирает диспетчер.',True,kind='checkbox',name='c-links',value='light')+choice('Не закрывается дверь','Не выбрано.',False,kind='checkbox',name='c-links',value='door')+choice('Не могу проверить','Полноценный вариант ответа.',True,name='c-observe'))

