for id,title,slug,func in [('C01','Основы','foundations',component_foundations),('C02','Действия и ввод','actions-and-inputs',component_actions),('C03','Навигация и оформление','navigation-and-preferences',component_nav),('C04','Предметные компоненты','domain-components',component_domain),('C05','Обратная связь','feedback',component_feedback),('C06','Подтверждения и история','confirmation-and-history',component_confirm)]:
    SCREENS[id]={'id':id,'title':title,'slug':slug,'role':'Библиотека','layout':'components','width':1440,'height':1000,'previous':'Использованные в M/A/D/X/R/B/S компоненты','next':'Повторное использование исходных компонентов','note':'Один сравнительный лист с полноценной светлой и тёмной колонками.','columns':{theme:func(theme).replace('name="', 'name="c-'+theme+'-') for theme in ('light','dark')}}

assert len(SCREENS)==62, (len(SCREENS),list(SCREENS))
# 56 экранов × 2 темы + 6 совместных листов = 118 обязательных artboards.
assert sum(1 if s['layout']=='components' else 2 for s in SCREENS.values())==118
(SRC/'catalog.json').write_text(json.dumps(SCREENS,ensure_ascii=False,indent=2))
(SRC/'catalog.js').write_text('window.KOREN_SCREENS = '+json.dumps(SCREENS,ensure_ascii=False)+';\nwindow.KOREN_ICONS = '+json.dumps(ICONS,ensure_ascii=False)+';\n')
vars=[]
for theme,ts in TOKENS['themes'].items():
    vars.append(f'[data-theme="{theme}"] {{'+''.join(f'--{k}:{v};' for k,v in ts.items())+'}\n')
(SRC/'theme-vars.css').write_text(''.join(vars))
print('Built',len(SCREENS),'design IDs; 118 themed artboards. Contrast minimum:',min(p['ratio'] for p in PAIRS if p['minimum']==4.5))
